1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .next-list { display: flex; flex-direction: column; gap: 8px; margin-top: 6px; }
26	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; }
27	  .preview .mini { width: 20px; height: 20px; background: transparent; }
28	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
29	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
30	  .help { font-size: 13px; color: #9097a6; }
31	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
32	  button {
33	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
34	    font: inherit; font-weight: 600; cursor: pointer;
35	  }
36	</style>
37	</head>
38	<body>
39	<div class="game">
40	  <div class="board" data-testid="board"></div>
41	  <div class="panel">
42	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
43	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
44	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
45	    <div class="stat"><div class="label">Hold</div><div class="preview" data-testid="hold-piece" data-piece=""></div></div>
46	    <div class="stat"><div class="label">Next</div><div class="next-list" data-testid="next-piece"></div></div>
47	    <div class="status" data-testid="status"><span data-testid="game-over" hidden></span></div>
48	    <button type="button" id="new-game">New game</button>
49	    <div class="help">
50	      <kbd>←</kbd> <kbd>→</kbd> move<br>
51	      <kbd>↑</kbd> rotate<br>
52	      <kbd>↓</kbd> soft drop<br>
53	      <kbd>Space</kbd> hard drop<br>
54	      <kbd>C</kbd> <kbd>Shift</kbd> hold
55	    </div>
56	  </div>
57	</div>
58	<script>
59	(function () {
60	  'use strict';
61	
62	  var ROWS = 20, COLS = 10;
63	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
64	  var COLORS = {
65	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
66	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
67	  };
68	  // Spawn orientation, as [row, col] offsets from the piece origin.
69	  var SHAPES = {
70	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
71	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
72	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
73	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
74	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
75	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
76	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
77	  };
78	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
79	  // Level rule (a project decision): the level starts at 1 and rises by one for every
80	  // LINES_PER_LEVEL lines cleared; it never goes down. Gravity runs every dropInterval() ms.
81	  var LINES_PER_LEVEL = 10;
82	  function dropInterval() { return Math.max(100, 1000 - (level - 1) * 100); }
83	  // Preview rule (a project decision): the panel shows only the next piece, in its colour.
84	  var PREVIEW_COUNT = 1;
85	
86	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
87	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
88	  var ROTATIONS = {};
89	  TYPES.forEach(function (t) {
90	    var n = t === 'O' ? 2 : 3;
91	    var states = [SHAPES[t]];
92	    for (var k = 1; k < 4; k++) {
93	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
94	    }
95	    ROTATIONS[t] = states;
96	  });
97	  ROTATIONS.I = [
98	    SHAPES.I,
99	    [[0, 2], [1, 2], [2, 2], [3, 2]],
100	    [[1, 0], [1, 1], [1, 2], [1, 3]],
101	    [[0, 1], [1, 1], [2, 1], [3, 1]]
102	  ];
103	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
104	  var KICKS = [0, -1, 1, -2, 2];
105	
106	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
107	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
108	  // right move during the delay restarts it, and so does a soft drop on a piece that is already
109	  // resting; these share one cap of MAX_RESTARTS per piece. A soft drop that cannot move the piece
110	  // never counts a tick. Hard drop locks at once.
111	  var LOCK_TICKS = 2;
112	  var MAX_RESTARTS = 3;
113	
114	  // Scoring rule (a project decision): a clear scores LINE_POINTS[rows cleared at once] times the
115	  // current level. Clearing rows together must always beat clearing the same rows in smaller
116	  // groups, so every entry must exceed any sum of smaller entries that adds up to the same rows.
117	  // Soft drop scores 1 per cell moved down by the player; hard drop scores 2 per cell dropped.
118	  var LINE_POINTS = [0, 100, 300, 500, 800];
119	  var SOFT_DROP_POINTS = 1;
120	  var HARD_DROP_POINTS = 2;
121	
122	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
123	  // `hold` is the held letter or null; `canHold` is false from a hold until the next lock.
124	  var board, current, queue, bag, score, level, lines, status, hold, canHold, timer = null;
125	
126	  // ---- DOM ----
127	  var boardEl = document.querySelector('[data-testid="board"]');
128	  var scoreEl = document.querySelector('[data-testid="score"]');
129	  var levelEl = document.querySelector('[data-testid="level"]');
130	  var linesEl = document.querySelector('[data-testid="lines"]');
131	  var nextEl = document.querySelector('[data-testid="next-piece"]');
132	  var gameOverEl = document.querySelector('[data-testid="game-over"]');
133	  var holdEl = document.querySelector('[data-testid="hold-piece"]');
134	  var cellEls = [];
135	  var itemEls = [];
136	  var miniEls = [];
137	
138	  // Fill a 4x2 grid element with mini cells; returns them as [row][col].
139	  function buildMini(grid) {
140	    var rows = [];
141	    for (var mr = 0; mr < 2; mr++) {
142	      rows.push([]);
143	      for (var mc = 0; mc < 4; mc++) {
144	        var m = document.createElement('div');
145	        m.className = 'mini';
146	        grid.appendChild(m);
147	        rows[mr].push(m);
148	      }
149	    }
150	    return rows;
151	  }
152	  var holdMinis = buildMini(holdEl);
153	
154	  for (var r = 0; r < ROWS; r++) {
155	    cellEls.push([]);
156	    for (var c = 0; c < COLS; c++) {
157	      var el = document.createElement('div');
158	      el.className = 'cell';
159	      el.setAttribute('data-testid', 'cell');
160	      el.setAttribute('data-row', String(r));
161	      el.setAttribute('data-col', String(c));
162	      boardEl.appendChild(el);
163	      cellEls[r].push(el);
164	    }
165	  }
166	  // One 4x2 mini grid per upcoming piece. The first grid keeps the older data-testid="next".
167	  for (var i = 0; i < PREVIEW_COUNT; i++) {
168	    var item = document.createElement('div');
169	    item.className = 'preview';
170	    item.setAttribute('data-testid', 'next-piece-item');
171	    nextEl.appendChild(item);
172	    itemEls.push(item);
173	    var grid = item;
174	    if (i === 0) {
175	      grid = document.createElement('div');
176	      grid.className = 'preview';
177	      grid.setAttribute('data-testid', 'next');
178	      item.className = '';
179	      item.appendChild(grid);
180	    }
181	    miniEls.push(buildMini(grid));
182	  }
183	
184	  function paint(el, type) {
185	    el.setAttribute('data-filled', type ? 'true' : 'false');
186	    el.setAttribute('data-piece', type || '');
187	    el.style.backgroundColor = type ? COLORS[type] : '';
188	  }
189	
190	  function paintMini(minis, type) {
191	    for (var mr = 0; mr < 2; mr++) {
192	      for (var mc = 0; mc < 4; mc++) paint(minis[mr][mc], '');
193	    }
194	    if (type) SHAPES[type].forEach(function (p) { paint(minis[p[0]][p[1]], type); });
195	  }
196	
197	  function render() {
198	    var view = board.map(function (row) { return row.slice(); });
199	    if (current) {
200	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
201	    }
202	    for (var r = 0; r < ROWS; r++) {
203	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
204	    }
205	
206	    for (var i = 0; i < PREVIEW_COUNT; i++) {
207	      var upcoming = queue[i] || '';
208	      itemEls[i].setAttribute('data-piece', upcoming);
209	      paintMini(miniEls[i], upcoming);
210	    }
211	    holdEl.setAttribute('data-piece', hold || '');
212	    paintMini(holdMinis, hold);
213	
214	    scoreEl.textContent = String(score);
215	    levelEl.textContent = String(level);
216	    linesEl.textContent = String(lines);
217	    var over = status === 'gameover';
218	    gameOverEl.hidden = !over;
219	    gameOverEl.textContent = over ? 'Game over' : '';
220	  }
221	
222	  // ---- Pieces ----
223	  function randomPiece() {
224	    if (!bag.length) {
225	      bag = TYPES.slice();
226	      for (var i = bag.length - 1; i > 0; i--) {
227	        var j = Math.floor(Math.random() * (i + 1));
228	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
229	      }
230	    }
231	    return bag.pop();
232	  }
233	
234	  // Keep at least PREVIEW_COUNT pieces waiting, so the preview is always full.
235	  function fillQueue() {
236	    while (queue.length < PREVIEW_COUNT) queue.push(randomPiece());
237	  }
238	
239	  function takeNext() {
240	    fillQueue();
241	    var type = queue.shift();
242	    fillQueue();
243	    return type;
244	  }
245	
246	  function pieceCells(piece) {
247	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
248	  }
249	
250	  function fits(cells) {
251	    return cells.every(function (p) {
252	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
253	    });
254	  }
255	
256	  // Bring in a piece of the given type (default: the next in the queue) at the spawn position.
257	  function spawn(type) {
258	    type = type || takeNext();
259	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
260	    if (!fits(pieceCells(piece))) {
261	      current = null;
262	      status = 'gameover';
263	      stopTimer();
264	      return;
265	    }
266	    current = piece;
267	  }
268	
269	  function move(dr, dc) {
270	    if (!current) return false;
271	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
272	    if (!fits(pieceCells(moved))) return false;
273	    current.row = moved.row;
274	    current.col = moved.col;
275	    return true;
276	  }
277	
278	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
279	  function shift(dc) {
280	    if (move(0, dc)) restartLock();
281	  }
282	
283	  // Down, one row. On a piece already resting it counts no lock tick and restarts the delay like a
284	  // sideways move, sharing the same cap.
285	  function softDrop() {
286	    if (move(1, 0)) {
287	      current.lockTicks = 0;
288	      score += SOFT_DROP_POINTS;
289	    } else {
290	      restartLock();
291	    }
292	  }
293	
294	  function restartLock() {
295	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
296	      current.lockTicks = 0;
297	      current.restarts++;
298	    }
299	  }
300	
301	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
302	  function rotateCW() {
303	    if (!current) return false;
304	    var rot = (current.rot + 1) % 4;
305	    for (var i = 0; i < KICKS.length; i++) {
306	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
307	      if (fits(pieceCells(turned))) {
308	        current.col = turned.col;
309	        current.rot = rot;
310	        return true;
311	      }
312	    }
313	    return false;
314	  }
315	
316	  // Remove every full row; the rows above drop down. Returns how many rows went.
317	  function clearLines() {
318	    var kept = board.filter(function (row) { return !row.every(Boolean); });
319	    var cleared = ROWS - kept.length;
320	    for (var i = 0; i < cleared; i++) kept.unshift(new Array(COLS).fill(''));
321	    board = kept;
322	    return cleared;
323	  }
324	
325	  function lock() {
326	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
327	    current = null;
328	    var cleared = clearLines();
329	    var before = Math.floor(lines / LINES_PER_LEVEL);
330	    lines += cleared;
331	    score += LINE_POINTS[cleared] * level;
332	    var gained = Math.floor(lines / LINES_PER_LEVEL) - before;
333	    if (gained > 0) {
334	      level += gained;
335	      startTimer();
336	    }
337	    canHold = true;
338	    spawn();
339	  }
340	
341	  // One gravity step. The real timer and tick() both run exactly this. Returns true if the piece moved down.
342	  function gravityStep() {
343	    if (status !== 'running' || !current) return false;
344	    if (move(1, 0)) {
345	      current.lockTicks = 0;
346	      return true;
347	    }
348	    current.lockTicks++;
349	    if (current.lockTicks >= LOCK_TICKS) lock();
350	    return false;
351	  }
352	
353	  function gravity() {
354	    gravityStep();
355	    render();
356	  }
357	
358	  function stopTimer() {
359	    if (timer !== null) { clearInterval(timer); timer = null; }
360	  }
361	
362	  function startTimer() {
363	    stopTimer();
364	    timer = setInterval(gravity, dropInterval());
365	  }
366	
367	  // Put the falling piece aside: bring in the held piece, or the next one if nothing is held.
368	  // Refused after a hold until a piece locks.
369	  function holdPiece() {
370	    if (!canHold) return;
371	    var from = hold;
372	    hold = current.type;
373	    canHold = false;
374	    current = null;
375	    spawn(from);
376	  }
377	
378	  // ---- Actions ----
379	  function input(action) {
380	    if (status !== 'running' || !current) return;
381	    if (action === 'left') shift(-1);
382	    else if (action === 'right') shift(1);
383	    else if (action === 'rotateCW') rotateCW();
384	    else if (action === 'softDrop') softDrop();
385	    else if (action === 'hold') holdPiece();
386	    else if (action === 'hardDrop') {
387	      while (move(1, 0)) score += HARD_DROP_POINTS;
388	      lock();
389	    }
390	    render();
391	  }
392	
393	  function toQueue(list) {
394	    return (Array.isArray(list) ? list : [])
395	      .map(function (t) { return String(t).toUpperCase(); })
396	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
397	  }
398	
399	  function newGame(list) {
400	    board = [];
401	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
402	    bag = [];
403	    queue = toQueue(list);
404	    score = 0;
405	    level = 1;
406	    lines = 0;
407	    hold = null;
408	    canHold = true;
409	    status = 'running';
410	    current = null;
411	    spawn();
412	    if (status === 'running') startTimer();
413	    render();
414	  }
415	
416	  function setQueue(list) {
417	    queue = toQueue(list);
418	    fillQueue();
419	    render();
420	  }
421	
422	  function setBoard(rows) {
423	    for (var r = 0; r < ROWS; r++) {
424	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
425	      for (var c = 0; c < COLS; c++) {
426	        var ch = line.charAt(c).toUpperCase();
427	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
428	      }
429	    }
430	    render();
431	  }
432	
433	  function getBoard() {
434	    return board.map(function (row) {
435	      return row.map(function (t) { return t || '.'; }).join('');
436	    });
437	  }
438	
439	  function getState() {
440	    return {
441	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
442	      next: queue.slice(),
443	      score: score,
444	      level: level,
445	      lines: lines,
446	      status: status,
447	      dropInterval: dropInterval(),
448	      hold: hold
449	    };
450	  }
451	
452	  function tick(n) {
453	    var steps = n === undefined ? 1 : n;
454	    for (var i = 0; i < steps; i++) gravity();
455	  }
456	
457	  // For testing: set the level. The gravity timer picks up the new interval.
458	  function setLevel(n) {
459	    level = Math.max(1, Math.floor(Number(n)) || 1);
460	    if (status === 'running') startTimer();
461	    render();
462	  }
463	
464	  window.__tetris = {
465	    setLevel: setLevel,
466	    newGame: newGame,
467	    setQueue: setQueue,
468	    setBoard: setBoard,
469	    tick: tick,
470	    input: input,
471	    getBoard: getBoard,
472	    getState: getState
473	  };
474	
475	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'rotateCW', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop', c: 'hold', C: 'hold', Shift: 'hold' };
476	  document.addEventListener('keydown', function (e) {
477	    var action = KEYS[e.key];
478	    if (!action) return;
479	    e.preventDefault();
480	    input(action);
481	  });
482	  document.getElementById('new-game').addEventListener('click', function (e) {
483	    e.currentTarget.blur();
484	    newGame();
485	  });
486	
487	  newGame();
488	})();
489	</script>
490	</body>
491	</html>
492
